    dirs[:] = [d for d in dirs if d != '.git' and d != '__pycache__']
    for file in files:
        if file.endswith(('.py', '.yaml', '.yml', '.json', '.sh', '.txt')):
            filepath = os.path.join(root, file)
            try:
                with open(filepath, 'rb') as f:
